import json
from collections import Counter

json_file = "/home/USER/runs/paper/qwen-hpl-u1-turns/frozen/seen-3/play/users/u032/system/state/workspace/programs/task-43d6a972.json"
with open(json_file, 'r') as f:
    demos = json.load(f)

def get_panels(grid):
    num_rows = len(grid)
    num_cols = len(grid[0])

    zero_rows = [i for i, row in enumerate(grid) if all(cell == 0 for cell in row)]
    zero_cols = [c for c in range(num_cols) if all(grid[r][c] == 0 for r in range(num_rows))]

    panel_row_ranges = []
    last = -1
    for zr in zero_rows:
        if zr > last + 1:
            panel_row_ranges.append((last + 1, zr))
        last = zr
    if last < num_rows - 1:
        panel_row_ranges.append((last + 1, num_rows))

    panel_col_ranges = []
    last = -1
    for zc in zero_cols:
        if zc > last + 1:
            panel_col_ranges.append((last + 1, zc))
        last = zc
    if last < num_cols - 1:
        panel_col_ranges.append((last + 1, num_cols))

    return panel_row_ranges, panel_col_ranges

def count8_in_panel(grid, pr, pc, pr_ranges, pc_ranges):
    rstart, rend = pr_ranges[pr]
    cstart, cend = pc_ranges[pc]

    count = 0
    for r in range(rstart, rend):
        for c in range(cstart, cend):
            if grid[r][c] == 8:
                count += 1
    return count

def find_background(grid):
    all_vals = []
    for row in grid:
        for val in row:
            all_vals.append(val)
    counts = Counter(all_vals)
    # Exclude 0 and find most common
    nonzero_counts = {k: v for k, v in counts.items() if k != 0}
    if nonzero_counts:
        return nonzero_counts.most_common(1)[0][0]
    return 0

def apply_transform(grid):
    pr_ranges, pc_ranges = get_panels(grid)
    background = find_background(grid)

    output = []
    for pr in range(len(pr_ranges)):
        row_list = []
        for pc in range(len(pc_ranges)):
            count8 = count8_in_panel(grid, pr, pc, pr_ranges, pc_ranges)
            if count8 == 2:
                row_list.append(1)
            else:
                row_list.append(background)
        output.append(row_list)

    return output

# Test on both demos
for i, d in enumerate(demos):
    grid = d["input"]
    expected = d["output"]
    result = apply_transform(grid)

    print(f"Demo {i}:")
    print(f"  Shape: {len(grid)}x{len(grid[0])}")
    print(f"  Background: {background}")
    print(f"  Result: {result}")
    print(f"  Expected: {expected}")
    print(f"  Match: {result == expected}")
    print()
